'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), C=RailCore;
let selectedAnomalies=new Set,selectedAssets=new Set,selectedPriorities=new Set,selectedEvaluations=new Set;
let profile=JSON.parse(localStorage.getItem('lc-profile')||'null');
let db,base,tracks,rail,sessions=[],activeId=null,position=null,tab='nearby',limit=60,offlineReady=false,saveQueue=Promise.resolve();
let range=Number(localStorage.getItem('lc-range')||500);if(!Number.isFinite(range)||range<1)range=500;
const active=()=>sessions.find(s=>s.id===activeId), editable=()=>active()&&!active().end;
const now=()=>new Date().toISOString(), date=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function openDialog(title,html){$('#dialogContent').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button id="closeDialog" aria-label="Fechar">×</button></div>${html}`;$('#closeDialog').onclick=()=>$('#dialog').close();if(!$('#dialog').open)$('#dialog').showModal()}
function warning(s){$('#locationWarning').hidden=!s;$('#locationWarning').textContent=s||''}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('mrs-notas-lc',1);r.onupgradeneeded=()=>r.result.createObjectStore('sessions',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function readAll(){return new Promise((resolve,reject)=>{const r=db.transaction('sessions').objectStore('sessions').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function persist(s){const copy=JSON.parse(JSON.stringify(s));saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{const t=db.transaction('sessions','readwrite');t.objectStore('sessions').put(copy);t.oncomplete=()=>{ $('#saveInfo').textContent='Salvo neste dispositivo · '+new Date().toLocaleTimeString('pt-BR');resolve()};t.onerror=t.onabort=()=>{const e=t.error||new Error('Não foi possível salvar');$('#saveInfo').textContent='Falha ao salvar. Exporte o relatório antes de sair.';toast('Falha no armazenamento. Seus registros ainda estão nesta tela; exporte uma cópia.');reject(e)}}));return saveQueue}
function restoredPosition(p){if(!p)return null;if(p.track){const id=tracks.findIndex(t=>t.asset===p.track.asset);if(id<0)return null;return {...p,trackId:id}}return p} function chooseSession(id){const old=sessions.find(v=>v.id===id);if(old&&!old.end&&!old.employeeId){completeLegacy(old);return}showWork();activeId=id;localStorage.setItem('lc-active',id);position=restoredPosition(active()?.lastPosition);render();setTab('treatments')}
async function loadCompressed(url,binary=false){const r=await fetch(url);if(!r.ok)throw Error('Não foi possível carregar '+url);const b=new Uint8Array(await r.arrayBuffer());const plain=b[0]===31&&b[1]===139?pako.ungzip(b):b;return binary?new Int32Array(plain.buffer.slice(plain.byteOffset,plain.byteOffset+plain.byteLength)):JSON.parse(new TextDecoder().decode(plain))}
function updateConnection(){ $('#connection').textContent=(navigator.onLine?'Online':'Offline')+' · '+(offlineReady?'Pronto para uso offline':'Preparando uso offline…')}
async function setupOffline(){if(!('serviceWorker'in navigator)){ $('#connection').textContent='Este navegador não oferece abertura offline.';return}try{await navigator.serviceWorker.register('sw.js');const reg=await navigator.serviceWorker.ready;const worker=reg.active;if(!worker)throw Error('Sem serviço offline');const ask=type=>new Promise((resolve,reject)=>{const ch=new MessageChannel;const timer=setTimeout(()=>reject(Error('Tempo excedido')),30000);ch.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data.ready)};worker.postMessage({type},[ch.port2])});let ready=await ask('CHECK_READY');if(!ready&&navigator.onLine)ready=await ask('PREPARE_OFFLINE');offlineReady=ready;updateConnection();if(!ready)toast('Preparação offline incompleta. Reabra com internet.')}catch(e){$('#connection').textContent='Preparação offline pendente';toast('O modo offline ainda não ficou pronto. Mantenha o app aberto com internet.')}}
function renderPosition(){const t=position&&(position.track||tracks[position.trackId]);$('#kmLabel').innerHTML=position?esc(C.fmtKm(position.km))+'<small>km ferroviário</small>':'—<small>km ferroviário</small>';$('#trackLabel').textContent=t?t.asset+' · '+t.name+' · Coord. '+t.coord:'Atualize o GPS ou informe o trecho e o km.';$('#sourceLabel').textContent=position?(position.source==='GPS'?'GPS · km estimado':'Km manual'):'Não definida';$('#positionMeta').textContent=position?'Atualizada em '+date(position.time)+(position.accuracy!=null?' · Precisão GPS ±'+Math.round(position.accuracy)+' m':'')+(position.distance!=null?' · Distância da referência '+Math.round(position.distance)+' m':''):'';$('#rangeLabel').textContent=position?'Faixa '+C.fmtKm(Math.max(0,position.km-range))+' a '+C.fmtKm(position.km+range)+' · ±'+range+' m':'Alcance: '+range+' m antes e depois'}
function treatmentFor(n){return active()?.treatments[n.id]}
function card(n,t){const high=/^[12]-/.test(n.priority),tone=t?({'Tratada':'treated','Inexistente':'absent','Alterar':'change','Manter':'keep'}[t.status]||''):'';return `<article class="note-card ${high?'high':''} ${tone}"><div class="card-top"><span class="note-id">Nota ${esc(/^\d+$/.test(String(n.id)) ? (String(n.id).replace(/^0+(?=\d)/,'') || '0') : n.id)}</span><span class="badge ${high?'high':''}">${esc(n.priority||'Criticidade não informada')}</span></div><h3>${esc(n.anomaly)}</h3><div class="km-row"><div><small>KM INICIAL</small>${esc(C.fmtKm(n.start))}</div><div><small>KM FINAL</small>${esc(C.fmtKm(n.end))}</div></div><div class="asset">${esc(n.asset)}</div><div class="card-bottom"><span>Centro ${esc(n.center)}</span><button class="evaluate-button" data-note="${esc(n.id)}" data-index="${n.index}">${esc(t?t.status+' · Ver':'Avaliar Nota')}</button></div></article>`}
function bindCards(container){container.querySelectorAll('[data-note]').forEach(el=>el.onclick=()=>{const t=active()?.treatments[el.dataset.note];const n=t?.note||base.notes.find(n=>n.index===Number(el.dataset.index));if(n)openNote(n)})}
function resetFilters(){selectedAnomalies.clear();selectedAssets.clear();selectedPriorities.clear();selectedEvaluations.clear();$('#priority').open=false;$('#evaluation').open=false;$('#assetFilter').open=false;$('#anomalyFilter').open=false;$('#search').value='';$('#scope').value='near';limit=60}
function renderChoiceFilters(){
 const groups=[{id:'priority',title:'Criticidade',selected:selectedPriorities,options:[...new Set(base.notes.map(n=>n.priority).filter(Boolean))].sort().map(v=>[v,v])},{id:'evaluation',title:'Avaliação',selected:selectedEvaluations,options:[['none','Não avaliadas'],...['Inexistente','Tratada','Alterar','Manter'].map(v=>[v,v])]}];
 for(const g of groups){$('#'+g.id+'Summary').textContent=g.selected.size?g.selected.size+' selecionada'+(g.selected.size>1?'s':''):'Todas';$('#'+g.id+'Options').innerHTML=g.options.map(([value,label])=>`<label class="choice-option"><input type="checkbox" data-choice="${esc(value)}" ${g.selected.has(value)?'checked':''}><span>${esc(label)}</span></label>`).join('');$('#'+g.id+'Options').querySelectorAll('[data-choice]').forEach(el=>el.onchange=()=>{if(el.checked)g.selected.add(el.dataset.choice);else g.selected.delete(el.dataset.choice);limit=60;renderNotes()});$('#clear'+g.id).onclick=()=>{g.selected.clear();limit=60;renderNotes()}}
}
function renderAssetFilter(list){const options=[...new Set(list.map(n=>n.asset))].sort((a,b)=>a.localeCompare(b,'pt-BR'));const allowed=new Set(options);selectedAssets=new Set([...selectedAssets].filter(a=>allowed.has(a)));const visible=!!position&&$('#scope').value!=='all'&&options.length>0;$('#assetFilter').hidden=!visible;$('#assetFilterSummary').textContent=selectedAssets.size?'Ativos · '+selectedAssets.size+' selecionados':'Ativos · todos na faixa';$('#assetOptions').innerHTML=options.map(a=>`<label class="asset-option"><input type="checkbox" data-asset="${esc(a)}" ${selectedAssets.has(a)?'checked':''}><span>${esc(a)}</span></label>`).join('');$('#assetOptions').querySelectorAll('[data-asset]').forEach(el=>el.onchange=()=>{if(el.checked)selectedAssets.add(el.dataset.asset);else selectedAssets.delete(el.dataset.asset);limit=60;renderNotes()});$('#clearAssets').onclick=()=>{selectedAssets.clear();renderNotes()}}
function renderAnomalyFilter(list){const options=[...new Set(list.map(n=>n.anomaly))].sort((a,b)=>a.localeCompare(b,'pt-BR'));const allowed=new Set(options);selectedAnomalies=new Set([...selectedAnomalies].filter(a=>allowed.has(a)));const visible=!!position&&$('#scope').value!=='all'&&options.length>0;$('#anomalyFilter').hidden=!visible;$('#anomalyFilterSummary').textContent=selectedAnomalies.size?'Anomalias · '+selectedAnomalies.size+' selecionadas':'Anomalias · todas na faixa';$('#anomalyOptions').innerHTML=options.map(a=>`<label class="asset-option"><input type="checkbox" data-anomaly="${esc(a)}" ${selectedAnomalies.has(a)?'checked':''}><span>${esc(a)}</span></label>`).join('');$('#anomalyOptions').querySelectorAll('[data-anomaly]').forEach(el=>el.onchange=()=>{if(el.checked)selectedAnomalies.add(el.dataset.anomaly);else selectedAnomalies.delete(el.dataset.anomaly);limit=60;renderNotes()});$('#clearAnomalies').onclick=()=>{selectedAnomalies.clear();renderNotes()}}
function renderNotes(){if(!base)return;renderChoiceFilters();let list;const scope=$('#scope').value;list=scope==='all'?base.notes.filter(n=>!n.locationIssue):C.near(base.notes,position,range,tracks);$('#nearCount').textContent=C.near(base.notes,position,range,tracks).length;const q=$('#search').value.toLocaleLowerCase('pt-BR');list=list.filter(n=>(!q||[n.id,n.asset,n.anomaly].join(' ').toLocaleLowerCase('pt-BR').includes(q))&&(!selectedPriorities.size||selectedPriorities.has(n.priority))&&(!selectedEvaluations.size||selectedEvaluations.has(treatmentFor(n)?.status||'none')));renderAssetFilter(scope==='all'?[]:list);renderAnomalyFilter(scope==='all'?[]:list);if(selectedAnomalies.size)list=list.filter(n=>selectedAnomalies.has(n.anomaly));if(selectedAssets.size)list=list.filter(n=>selectedAssets.has(n.asset));list.sort((a,b)=>(a.start??Infinity)-(b.start??Infinity)||a.id.localeCompare(b.id));$('#listTitle').textContent=scope==='all'?'Notas com localização':'Notas próximas';$('#resultInfo').textContent=list.length+' registro'+(list.length===1?'':'s');$('#notesList').innerHTML=list.length?list.slice(0,limit).map(n=>card(n,treatmentFor(n))).join(''):`<div class="empty"><strong>${!position&&scope==='near'?'Defina sua localização':'Nenhuma Nota encontrada'}</strong>${!position&&scope==='near'?'Use o GPS ou informe o trecho e o km para consultar a faixa.':'Confira a faixa, o trecho selecionado e os filtros.'}</div>`;$('#moreBtn').hidden=list.length<=limit;bindCards($('#notesList'))}
function renderTreatments(){const s=active(),ts=Object.values(s?.treatments||{}).sort((a,b)=>a.note.id.localeCompare(b.note.id));$('#treatCount').textContent=ts.length;$('#finishBtn').textContent=s?.end?'Exportar relatório':'Finalizar inspeção';$('#finishBtn').disabled=!s;$('#treatmentsList').innerHTML=ts.length?ts.map(t=>card(t.note,t)).join(''):'<div class="empty"><strong>Nenhuma tratativa registrada</strong>Abra uma Nota e registre sua constatação.</div>';bindCards($('#treatmentsList'))}
function renderHistory(){const list=[...sessions].sort((a,b)=>b.start.localeCompare(a.start));$('#historyList').innerHTML=list.length?list.map(s=>`<article class="history-card"><div class="card-top"><strong>${esc(s.name)}</strong><span class="badge">${s.end?'Concluída':'Em andamento'}</span></div><p>${esc(s.collaborator)} · ${date(s.start)}</p><p>${Object.keys(s.treatments).length} tratativas · Base ${esc(s.version)}</p><button data-session="${s.id}">${s.end?'Ver e exportar':'Retomar conferência'}</button></article>`).join(''):'<div class="empty"><strong>Seu histórico aparecerá aqui</strong>Conferências são guardadas neste dispositivo.</div>';$('#historyList').querySelectorAll('[data-session]').forEach(el=>el.onclick=()=>chooseSession(el.dataset.session))}
function render(){if(!base)return;const s=active();$('#sessionInfo').innerHTML=s?`<strong>${esc(s.origin||s.name)}</strong><p>${esc(s.collaborator)}${s.employeeId?' · Matrícula '+esc(s.employeeId):''} · ${s.end?'Finalizada':'Em andamento'} · ${date(s.start)}</p>`:'<strong>Histórico de inspeções</strong>';$('#finishTopBtn').hidden=!s;$('#finishTopBtn').textContent=s?.end?'Ver relatório':'Finalizar inspeção';$('#beginAgainBtn').hidden=!!s&&!s.end;renderPosition();renderNotes();renderTreatments();renderHistory()}
function setTab(t){tab=t;['nearby','treatments','history'].forEach(v=>{ $('#'+v+'View').hidden=t!==v;document.querySelector(`[data-tab="${v}"]`).classList.toggle('selected',v===t)});render()}
function showStart(){if(!base||!db){toast('Aguarde a preparação da base.');return}$('#appWork').hidden=true;$('#welcome').hidden=false;$('#startFields').innerHTML=`<form id="sessionForm" class="fields"><div class="identity-fields"><label class="field">Matrícula<input name="employeeId" required maxlength="40" autocomplete="off" value="${esc(profile?.employeeId||'')}"></label><label class="field">Nome do avaliador<input name="collaborator" required autocomplete="name" maxlength="120" value="${esc(profile?.name||'')}"></label></div><p class="dialog-note">Matrícula e nome ficam salvos neste dispositivo para as próximas inspeções.</p><label class="field">Origem da inspeção<input name="origin" required maxlength="160" placeholder="Ex.: inspeção de trecho ou fiscalização de serviço"></label><label class="field">Foto da inspeção<input name="photo" type="file" accept="image/*"><small class="muted">Selecione uma foto da galeria ou tire uma foto pelo celular.</small></label><div class="button-row"><button id="startInspectionBtn" class="primary">Iniciar inspeção</button><button type="button" id="startHistoryBtn">Ver histórico</button></div></form>`;const inProgress=sessions.filter(v=>!v.end);$('#resumeList').innerHTML=inProgress.length?'<h2>Retomar inspeção</h2>'+inProgress.map(v=>`<button class="resume" data-resume="${v.id}">${esc(v.origin||v.name)} · ${date(v.start)}<small>${esc(v.collaborator)} · ${Object.keys(v.treatments).length} avaliações</small></button>`).join(''):'';$('#resumeList').querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>chooseSession(b.dataset.resume));$('#startHistoryBtn').onclick=()=>{showWork();setTab('history')};$('#sessionForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('collaborator')||'').trim(),employeeId=String(f.get('employeeId')||'').trim(),origin=String(f.get('origin')||'').trim();if(!name||!employeeId||!origin){toast('Preencha matrícula, nome e origem.');return}const file=f.get('photo');$('#startInspectionBtn').disabled=true;try{const photo=file?.size?await resizePhoto(file):null;profile={name,employeeId};localStorage.setItem('lc-profile',JSON.stringify(profile));const inspection={id:crypto.randomUUID(),collaborator:name,employeeId,origin,name:origin,photo,start:now(),end:null,version:base.version,treatments:{},lastPosition:null};await persist(inspection);sessions.push(inspection);activeId=inspection.id;localStorage.setItem('lc-active',activeId);position=null;showWork();setTab('nearby');toast('Inspeção iniciada')}catch(e){toast('Não foi possível iniciar. Confira a foto e tente novamente.');console.error(e)}finally{$('#startInspectionBtn').disabled=false}}}
function completeLegacy(inspection){openDialog('Completar identificação',`<form id="legacyForm" class="fields"><p class="dialog-note">Esta inspeção começou na versão anterior. Informe a matrícula para continuar. Avaliações anteriores permanecem com seus dados originais.</p><label class="field">Matrícula<input name="employeeId" required maxlength="40" value="${esc(profile?.employeeId||'')}"></label><label class="field">Nome<input name="name" required maxlength="120" value="${esc(inspection.collaborator)}"></label><button class="primary">Retomar inspeção</button></form>`);$('#legacyForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),employeeId=String(f.get('employeeId')||'').trim(),name=String(f.get('name')||'').trim();if(!employeeId||!name)return;for(const t of Object.values(inspection.treatments))if(t.employeeId===undefined)t.employeeId='';inspection.employeeId=employeeId;inspection.collaborator=name;inspection.origin=inspection.origin||inspection.name;profile={employeeId,name};localStorage.setItem('lc-profile',JSON.stringify(profile));await persist(inspection);$('#dialog').close();chooseSession(inspection.id)}}
function newSession(){showStart()}
function showWork(){$('#welcome').hidden=true;$('#appWork').hidden=false}
async function resizePhoto(file){if(!file.type.startsWith('image/'))throw Error('Selecione uma imagem');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image;image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Imagem não suportada'));image.src=url});const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const context=canvas.getContext('2d');context.fillStyle='white';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.8)}finally{URL.revokeObjectURL(url)}}
function editProfile(){openDialog('Cadastro do avaliador',`<form id="profileForm" class="fields"><label class="field">Matrícula<input name="employeeId" required maxlength="40" value="${esc(profile?.employeeId||'')}"></label><label class="field">Nome<input name="name" required maxlength="120" value="${esc(profile?.name||'')}"></label><p class="dialog-note">O cadastro será usado nas próximas inspeções. As avaliações anteriores e a inspeção atual mantêm a identificação original.</p><button class="primary">Salvar cadastro</button></form>`);$('#profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim(),employeeId=String(f.get('employeeId')||'').trim();if(!name||!employeeId)return;profile={name,employeeId};localStorage.setItem('lc-profile',JSON.stringify(profile));$('#dialog').close();toast('Cadastro salvo para as próximas inspeções')}}
function setPosition(p){resetFilters();p.track=tracks[p.trackId];position=p;const s=active();if(s&&!s.end){s.lastPosition=p;persist(s).catch(()=>{})}render();warning('')}
function settings(){openDialog('Configurações',`<form id="rangeForm" class="fields"><label class="field">Alcance antes e depois<select name="preset"><option value="250" ${range===250?'selected':''}>250 metros</option><option value="500" ${range===500?'selected':''}>500 metros</option><option value="custom" ${![250,500].includes(range)?'selected':''}>Personalizado</option></select></label><label class="field">Valor personalizado em metros<input name="custom" type="number" min="1" max="50000" step="1" value="${range}"></label><p class="dialog-note">A distância é aplicada para cada lado, ao longo da quilometragem da mesma linha.</p><button class="primary">Salvar configuração</button><button type="button" id="editProfileBtn">Editar matrícula e nome</button></form>`);$('#editProfileBtn').onclick=editProfile;$('#rangeForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=f.get('preset')==='custom'?Number(f.get('custom')):Number(f.get('preset'));if(!Number.isInteger(v)||v<1||v>50000){toast('Informe um alcance entre 1 e 50.000 metros.');return}range=v;localStorage.setItem('lc-range',range);$('#dialog').close();limit=60;render()}}
function manual(){
 if(!tracks||!rail){toast('Aguarde a preparação da base.');return}
 openDialog('Informar trecho e quilômetro',`<form id="manualForm" class="fields"><label class="field">Quilômetro<input id="manualKm" name="km" required inputmode="decimal" placeholder="Ex.: 210+500 ou 210,500" value="${position?C.fmtKm(position.km):''}"></label><label class="field">Filtrar trecho ou ativo<input id="trackSearch" placeholder="Ex.: FBJ, LC1, FFP"></label><label class="field">Linha / ativo da referência<select id="trackSelect" name="track" required></select></label><p id="manualRangeInfo" class="dialog-note" aria-live="polite"></p><p class="dialog-note">A lista mostra apenas linhas cuja quilometragem cruza a faixa informada. Selecione uma referência para identificar a coordenação e o ramal. A consulta inclui as notas de todas as linhas, AMVs e ativos dessa região dentro da faixa, mesmo que você filtre a lista por nome. A localização manual não recebe coordenadas fictícias.</p><button id="manualSubmit" class="primary">Consultar faixa</button></form>`);
 const select=$('#trackSelect'),input=$('#manualKm');
 function updateTracks(preferred=select.value){
  const k=C.manualKm(input.value),q=$('#trackSearch').value.trim().toUpperCase();
  const ids=(k===null?tracks.map((t,i)=>i):C.tracksAtKm(rail,k,range)).filter(i=>tracks[i]&&Object.values(tracks[i]).join(' ').toUpperCase().includes(q));
  select.innerHTML='<option value="">'+(ids.length?'Selecione a linha / ativo da referência':'Nenhuma linha / ativo nesta faixa')+'</option>'+trackOptions(ids);
  select.value=preferred!==''&&ids.includes(Number(preferred))?String(preferred):'';
  select.disabled=!ids.length;
  $('#manualSubmit').disabled=k===null||!ids.length;
  $('#manualRangeInfo').textContent=k===null?'Informe um km válido para filtrar as linhas pela tolerância de ±'+range+' m.':'Faixa '+C.fmtKm(Math.max(0,k-range))+' a '+C.fmtKm(k+range)+' · ±'+range+' m · '+ids.length+' linhas / ativos compatíveis'+(ids.length?'':'. Confira o km e o filtro de trecho.');
 }
 input.oninput=()=>updateTracks();$('#trackSearch').oninput=()=>updateTracks();updateTracks(position?String(position.trackId):'');
 $('#manualForm').onsubmit=e=>{e.preventDefault();const k=C.manualKm(input.value),id=Number(select.value);if(k===null||!select.value||!tracks[id]||!C.tracksAtKm(rail,k,range).includes(id)){toast('Selecione uma linha compatível com o km e a tolerância.');return}setPosition({trackId:id,km:k,source:'Manual',time:now(),lat:null,lon:null,accuracy:null});$('#dialog').close()}
}
function trackOptions(ids){return ids.map(i=>`<option value="${i}">${esc(tracks[i].asset+' · '+tracks[i].name+' · '+tracks[i].coord)}</option>`).join('')}
