function finish(){const s=active();if(!s)return;const ts=Object.values(s.treatments);openDialog(s.end?'Relatório da conferência':'Revisar e finalizar inspeção',`<p><strong>${esc(s.name)}</strong><br>${esc(s.collaborator)} · Matrícula ${esc(s.employeeId||'Não informada')}</p><div class="details-grid">${['Tratada','Inexistente','Alterar','Manter'].map(v=>`<div><span class="badge">${v}</span><p>${ts.filter(t=>t.status===v).length} Notas</p></div>`).join('')}</div><p class="dialog-note">Tratadas e inexistentes são indicações para análise de conclusão pela assistente. Alterações são encaminhadas separadamente. “Manter” não indica encerramento. Notas não avaliadas não recebem classificação. O relatório não encerra Notas no sistema da MRS.</p>${!s.end?'<button id="confirmFinish" class="primary">Confirmar finalização</button>':''}<div class="button-row"><button id="pdfBtn">Baixar PDF</button><button id="csvBtn">Baixar CSV</button><button id="shareBtn">Compartilhar PDF e CSV</button></div><p class="dialog-note">O botão Compartilhar PDF e CSV envia os dois arquivos juntos ao aplicativo escolhido. As conferências continuam salvas. Para importar CSV no Excel, use UTF-8 e separador ponto e vírgula; defina identificadores e códigos como Texto.</p><p id="exportMessage" class="muted"></p><button id="clearCacheBtn" class="text-button small" ${s.end?'':'hidden'}>Limpar cache</button><div id="cacheConfirm" class="warning" hidden>Limpar o cache remove os arquivos preparados para uso offline. O histórico, as avaliações, as fotos e o cadastro serão preservados. Será necessário abrir novamente com internet.<div class="button-row"><button id="confirmClearCache" class="quiet">Confirmar limpeza</button><button id="cancelClearCache">Cancelar</button></div></div>`);$('#clearCacheBtn').onclick=()=>{$('#cacheConfirm').hidden=false};$('#cancelClearCache').onclick=()=>{$('#cacheConfirm').hidden=true};$('#confirmClearCache').onclick=clearAppCache;const done=async()=>{if(!s.end){s.end=now();try{await persist(s);render()}catch(e){s.end=null;throw e}}};if($('#confirmFinish'))$('#confirmFinish').onclick=async()=>{await done();$('#confirmFinish').hidden=true;$('#exportMessage').textContent='Inspeção finalizada. Baixe ou compartilhe os dois arquivos.';$('#clearCacheBtn').hidden=false};$('#pdfBtn').onclick=async()=>{await done();await downloadPdf(s)};$('#csvBtn').onclick=async()=>{await done();downloadCsv(s)};$('#shareBtn').onclick=async()=>{await done();await exportFiles(s,true)}}
