function csvBlob(s){const headers=['Inspeção','Colaborador','Matrícula','Origem da inspeção','Início conferência','Conclusão conferência','Base conferência','Número da Nota','Ativo','Km inicial','Km final','Criticidade','Código anomalia','Anomalia','TAM','Descrição original','Tratativa','Texto livre','Data avaliação','Base avaliação','Origem localização','Ativo localização','Km avaliação','Latitude','Longitude','Precisão GPS metros','Lado da anomalia','Data/hora clique avaliar nota','Data/hora leitura GPS do clique','Data/hora gravação'];const records=Object.values(s.treatments);const rows=records.map(t=>{const p=t.position,track=p&&(p.track||tracks[p.trackId]);return [s.name,t.collaborator,t.employeeId??s.employeeId??'',s.origin||s.name,s.start,s.end,s.version,t.note.id,t.note.asset,C.fmtKm(t.note.start),C.fmtKm(t.note.end),t.note.priority,t.note.code,t.note.anomaly,t.note.tam,t.note.description,t.status,t.text,t.time,t.version,p?.source,track?.asset,p?C.fmtKm(p.km):'',t.clickTime?p?.lat:null,t.clickTime?p?.lon:null,t.clickTime?p?.accuracy:null,C.noteSide(t.note),t.clickTime||'',t.clickTime?p?.gpsTime||'':'',t.savedTime||'']});if(!records.length){const empty=Array(headers.length).fill('');[s.name,s.collaborator,s.employeeId||'',s.origin||s.name,s.start,s.end,s.version].forEach((v,i)=>empty[i]=v);empty[headers.indexOf('Tratativa')]='Nenhuma Nota avaliada';rows.push(empty)}const safe=v=>{let z=String(v??'');if(/^[=+@-]/.test(z)&&!/^-[0-9]+(?:\.[0-9]+)?$/.test(z))z="'"+z;return '"'+z.replace(/"/g,'""')+'"'};return new Blob(['\ufeff'+[headers.map((h,i)=>(i>=7&&i<=15||i===26?'NOTA ORIGINAL | ':'INSPEÇÃO | ')+h),...rows].map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})}
