function downloadCsv(s){downloadBlob(csvBlob(s),filename(s)+'.csv')}
async function pdfBlob(s){const {PDFDocument,StandardFonts,rgb,PDFName,PDFString}=PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);const photo=s.photo?await pdf.embedJpg(s.photo):null;let page,y;const W=595,H=842,M=32;const clean=v=>String(v??'').replace(/[^\x0A\x0D\x20-\x7E\u00A0-\u00FF\u2013\u2014\u2018\u2019\u201C\u201D\u2022]/g,' ');function text(v,x,yy,size=9,f=font,color=rgb(.12,.2,.28)){page.drawText(clean(v),{x,y:yy,size,font:f,color})}function wrap(v,width,size=9){const lines=[];for(const paragraph of clean(v).replace(/\r/g,'').split('\n')){let line='';for(const word of paragraph.split(' ')){const candidate=line?line+' '+word:word;if(font.widthOfTextAtSize(candidate,size)<=width){line=candidate;continue}if(line){lines.push(line);line=''}for(const char of word){if(font.widthOfTextAtSize(line+char,size)>width){lines.push(line);line=''}line+=char}}lines.push(line)}return lines}function newPage(){page=pdf.addPage([W,H]);page.drawRectangle({x:0,y:H-70,width:W,height:70,color:rgb(.025,.21,.38)});text('MRS | NOTAS LC - CONFERÊNCIA EM CAMPO',M,H-30,13,bold,rgb(1,1,1));text(wrap(s.name,W-2*M,10)[0],M,H-49,10,font,rgb(1,1,1));y=H-90;for(const line of wrap('Avaliador: '+s.collaborator+' | Matrícula: '+(s.employeeId||'Não informada'),W-2*M)){text(line,M,y);y-=12}for(const line of wrap('Origem: '+(s.origin||s.name),W-2*M)){text(line,M,y);y-=12}y-=3;text('Início: '+date(s.start)+' | Conclusão: '+date(s.end),M,y);y-=15;text('Base: '+s.version+' | Indicações para avaliação da coordenação',M,y);y-=20;if(photo&&pdf.getPageCount()===1){const dims=photo.scale(Math.min(160/photo.width,115/photo.height));page.drawImage(photo,{x:M,y:y-dims.height,width:dims.width,height:dims.height});y-=dims.height+22}text('NOTA / ATIVO / LOCALIZAÇÃO',M,y,9,bold);text('TRATATIVA / ANOMALIA / OBSERVAÇÕES',M+220,y,9,bold);y-=10;page.drawLine({start:{x:M,y},end:{x:W-M,y},thickness:1,color:rgb(.7,.77,.82)});y-=15}newPage();const ts=Object.values(s.treatments).sort((a,b)=>['Tratada','Inexistente','Alterar','Manter'].indexOf(a.status)-['Tratada','Inexistente','Alterar','Manter'].indexOf(b.status)||a.note.id.localeCompare(b.note.id));if(!ts.length)text('Nenhuma Nota avaliada nesta inspeção.',M,y,11,bold);for(const t of ts){const n=t.note,p=t.position,tr=p&&(p.track||tracks[p.trackId]);const image=t.evidencePhoto?await pdf.embedJpg(t.evidencePhoto):null,dims=image?image.scale(Math.min((W-2*M-220)/image.width,220/image.height)):null;let evidenceDone=!image;const left=wrap('Nota '+n.id+'\n'+n.asset+'\nKm '+C.fmtKm(n.start)+' a '+C.fmtKm(n.end)+'\nCriticidade: '+(n.priority||'Não informada')+'\nTAM: '+(n.tam||'Não informado')+'\nAvaliador: '+t.collaborator+' | Matrícula: '+((t.employeeId??s.employeeId)||'Não informada')+'\n'+(t.clickTime?'Clique avaliar: '+date(t.clickTime):'Avaliação (registro antigo): '+date(t.time))+'\nBase: '+t.version+'\n'+(p?.gpsTime?'GPS lido: '+date(p.gpsTime)+'\n':'')+(p? p.source+' - km '+C.fmtKm(p.km)+(t.clickTime?'':' (última consulta; registro antigo)')+'\n'+(tr?.asset||'')+'\n'+(p.lat!=null?'Lat '+p.lat+' | Lon '+p.lon:'Sem coordenadas')+(p.accuracy!=null?'\nPrecisão GPS: '+Math.round(p.accuracy)+' m':''):'Localização não registrada'),205,8);const right=wrap(t.status+'\n'+n.anomaly+'\nLado na nota: '+C.noteSide(n)+'\nCódigo: '+(n.code||'Não informado')+'\n'+(t.text||'Sem observação adicional.'),W-2*M-220,9);let cursor=0;while(cursor<Math.max(left.length,right.length)){if(y<95)newPage();const top=y,available=Math.floor((y-70)/12),count=Math.min(available,Math.max(left.length,right.length)-cursor);for(let j=0;j<count;j++){if(left[cursor+j])text(left[cursor+j],M,y-j*12,8);if(right[cursor+j])text(right[cursor+j],M+220,y-j*12,9)}const rightEnd=Math.max(0,Math.min(count,right.length-cursor)),photoTop=top-rightEnd*12-8;let photoBottom=null;if(!evidenceDone&&cursor+count>=right.length&&photoTop-dims.height-30>=65){text('Evidência da Nota '+n.id,M+220,photoTop,9,bold);page.drawImage(image,{x:M+220,y:photoTop-15-dims.height,width:dims.width,height:dims.height});photoBottom=photoTop-15-dims.height-12;evidenceDone=true}y=Math.min(top-count*12,photoBottom??Infinity);cursor+=count;if(cursor<Math.max(left.length,right.length)){newPage();text('Continuação da Nota '+n.id,M,y,9,bold);y-=18}}if(!evidenceDone){newPage();text('Evidência da Nota '+n.id,M+220,y,9,bold);y-=15;page.drawImage(image,{x:M+220,y:y-dims.height,width:dims.width,height:dims.height});y-=dims.height+15}if(p?.lat!=null&&p?.lon!=null){if(y<75)newPage();text('Abrir mapa',M,y,9,font,rgb(.04,.3,.65));const link=pdf.context.register(pdf.context.obj({Type:'Annot',Subtype:'Link',Rect:[M,y-2,M+80,y+10],Border:[0,0,0],A:{Type:'Action',S:'URI',URI:PDFString.of('https://www.google.com/maps/search/?api=1&query='+p.lat+','+p.lon)}}));page.node.addAnnot(link);y-=15}page.drawLine({start:{x:M,y:y-4},end:{x:W-M,y:y-4},thickness:.5,color:rgb(.8,.85,.9)});y-=20}const pages=pdf.getPages();pages.forEach((pg,i)=>pg.drawText('Página '+(i+1)+' de '+pages.length+' | Registro de campo; não comprova encerramento no sistema MRS.',{x:M,y:25,size:8,font}));return new Blob([await pdf.save()],{type:'application/pdf'})}
async function downloadPdf(s){try{$('#exportMessage').textContent='Gerando PDF…';const blob=await pdfBlob(s);downloadBlob(blob,filename(s)+'.pdf');$('#exportMessage').textContent='PDF gerado.'}catch(e){toast('Não foi possível gerar o PDF. Seus registros continuam salvos.');console.error(e)}}
async function exportFiles(s,share){try{$('#exportMessage').textContent='Preparando arquivos…';const pdf=await pdfBlob(s),csv=csvBlob(s),files=[new File([pdf],filename(s)+'.pdf',{type:'application/pdf'}),new File([csv],filename(s)+'.csv',{type:'text/csv'})];if(share&&navigator.canShare?.({files})){await navigator.share({files,title:s.name});$('#exportMessage').textContent='Arquivos enviados para compartilhamento.'}else{downloadBlob(pdf,files[0].name);downloadBlob(csv,files[1].name);$('#exportMessage').innerHTML='PDF e CSV preparados. Se o navegador permitir apenas um download por vez, use os botões individuais.'}}catch(e){if(e.name!=='AbortError'){toast('Falha na exportação. Use os botões individuais.');console.error(e)}}}
async function clearAppCache(){try{await saveQueue;const s=active();if(!s?.end){toast('Finalize a inspeção antes de limpar o cache.');return}if(!('caches'in window)){toast('Este navegador não permite limpar o cache do app.');return}$('#confirmClearCache').disabled=true;const keys=await caches.keys();for(const key of keys)if(key.startsWith('notas-lc-'))await caches.delete(key);offlineReady=false;updateConnection();$('#cacheConfirm').hidden=true;$('#exportMessage').textContent='Cache limpo. Histórico e avaliações preservados. Abra novamente com internet antes de usar offline.';toast('Cache limpo. Os dados das inspeções foram preservados.')}catch(e){toast('Não foi possível limpar o cache.');console.error(e)}finally{$('#confirmClearCache').disabled=false}}
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController;const tool={name:'consultar_notas_por_km',title:'Consultar Notas por km',description:'Configura a consulta por linha e quilômetro e exibe as Notas próximas; não registra tratativas.',inputSchema:{type:'object',properties:{trackId:{type:'integer'},kmMeters:{type:'integer'},rangeMeters:{type:'integer'}},required:['trackId','kmMeters'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!editable())throw Error('Inicie uma inspeção antes de consultar pelo agente');if(!input||!Number.isInteger(input.trackId)||!tracks[input.trackId]||!Number.isInteger(input.kmMeters)||input.kmMeters<0||(input.rangeMeters!==undefined&&(!Number.isInteger(input.rangeMeters)||input.rangeMeters<1||input.rangeMeters>50000)))throw Error('Trecho, km ou alcance inválido');if(input.rangeMeters){range=input.rangeMeters;localStorage.setItem('lc-range',range)}setPosition({trackId:input.trackId,km:input.kmMeters,source:'Manual',time:now(),lat:null,lon:null,accuracy:null});setTab('nearby');return {track:tracks[input.trackId].asset,km:C.fmtKm(position.km),notes:C.near(base.notes,position,range,tracks).map(n=>({id:n.id,anomaly:n.anomaly,start:n.start,end:n.end}))}}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch(e){}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
async function init(){try{[db,base,tracks,rail]=await Promise.all([openDB(),loadCompressed('notes.json.gz').then(C.parseBase),fetch('tracks.json').then(r=>{if(!r.ok)throw Error('Base de linhas indisponível');return r.json()}),loadCompressed('rail.bin.gz',true)]);sessions=await readAll();C.classifyLocations(base.notes,tracks,rail);activeId=localStorage.getItem('lc-active');position=restoredPosition(active()?.lastPosition);const excluded=base.notes.filter(n=>n.locationIssue).length;$('#baseInfo').textContent='Base '+base.version+' · '+(base.notes.length-excluded)+' Notas com km · '+excluded+' com km em branco';render();if(active()&&!active().end&&active().employeeId)showWork();else showStart();registerTools();setupOffline();navigator.storage?.persist?.().catch(()=>{});const duplicates=base.notes.length-new Set(base.notes.map(n=>n.id)).size;if(duplicates)toast(duplicates+' números de Nota repetidos na base; revise antes de tratar.')}catch(e){$('#connection').textContent='Não foi possível preparar o aplicativo';$('#notesList').innerHTML='<div class="empty"><strong>Falha ao carregar dados</strong>Reabra com internet para preparar o uso offline. Se persistir, consulte o responsável pelo aplicativo.</div>';console.error(e)}}
$('#beginAgainBtn').onclick=showStart;$('#finishTopBtn').onclick=finish;$('#settingsBtn').onclick=settings;$('#manualBtn').onclick=manual;$('#gpsBtn').onclick=gps;$('#finishBtn').onclick=finish;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));['search','scope'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{limit=60;renderNotes()}));$('#moreBtn').onclick=()=>{limit+=60;renderNotes()};window.addEventListener('online',()=>{updateConnection();setupOffline()});window.addEventListener('offline',updateConnection);window.addEventListener('storage',e=>{if(e.key==='lc-active')toast('Outra aba está usando este aplicativo. Evite editar a mesma conferência em duas abas.');});init();
